#pragma once
#include "kstationVoiceUpdateTask.h"
#include "kstationVoiceAllocationTask.h"
#include "kstationMidiEventTask.h"
#include <optional>
namespace kstation {
class ControllerVoiceEnvelopeSequence final {
 using B=VoiceParameterBlendTask;using BS=B::Stage;using E=VoiceParameterEnvelopeTask;using ES=E::Stage;using V=VoiceAddressTask;using F=MidiFloatConvertTask;using FS=F::Stage;using P=VoiceParameterPairTask;using PS=P::Stage;using Q=VoiceParameterScaledTask;using QS=Q::Stage;
public:
 explicit ControllerVoiceEnvelopeSequence(uint32_t patch):patch_(patch){blend_.emplace(patch,0);}bool complete()const{return stage_==13;}bool awaitingDsp()const{return blend_?blend_->child()==B::Child::Dsp:env_?env_->child()==E::Child::Dsp:pair_?pair_->child()==P::Child::Dsp:scaled_&&scaled_->awaitingDsp();}uint32_t word()const{return blend_?blend_->word():env_?env_->word():pair_?pair_->word():scaled_->word();}bool resumeDsp(){if(!awaitingDsp())return false;bool ok=blend_?blend_->resumeChild():env_?env_->resumeChild():pair_?pair_->resumeChild():scaled_->resumeDsp();if(ok)selectNext();return ok;}
 bool stackWrites()const{if(voice_||floating_)return false;if(pair_){auto s=pair_->stage();return s==PS::DispatchSquare||s==PS::DispatchFloat||s==PS::DispatchFinal;}if(scaled_)return scaled_->stage()==QS::Dispatch;if(blend_)return blend_->stage()==BS::DispatchVoice||blend_->stage()==BS::DispatchDsp;return env_->stage()==ES::DispatchFloat||env_->stage()==ES::DispatchDsp;}
 unsigned nextClocks()const{if(complete())return 0;if(voice_){V::Credits c{3,7};return voice_->nextClocks(c);}if(floating_){switch(floating_->stage()){case FS::Complete:return 0;case FS::CompareMinimum:return 6;case FS::Return:return 7;default:return 3;}}uint32_t a=0;unsigned width=0;access(a,width);if(pair_){P::Credits c{width?bus(a,width):0,10};return pair_->nextClocks(c);}if(scaled_){Q::Credits c{width?bus(a,width):0,10};return scaled_->nextClocks(c);}if(blend_){B::Credits c{width?bus(a,width):0,10};return blend_->nextClocks(c);}E::Credits c{width?bus(a,width):0,10};return env_->nextClocks(c);}
 template<class R>unsigned advanceBefore(unsigned budget,R&&read){auto cost=nextClocks();if(!cost||cost>budget)return 0;if(voice_){V::Credits c{3,7};auto used=voice_->advanceBefore(cost,c,[&](){return read(0xd023,1,cost);});if(voice_->complete()){auto a=voice_->address();voice_.reset();blend_->resumeChild(a);}return used;}if(floating_){if(!floating_->advance())return 0;if(floating_->complete()){auto v=floating_->result();floating_.reset();if(pair_)pair_->resumeChild(v);else env_->resumeChild(v);}return cost;}uint32_t a=0;unsigned width=0;access(a,width);if(pair_){P::Credits c{width?bus(a,width):0,10};auto used=pair_->advanceBefore(cost,c,[&](P::Read){return read(a&0xffffff,width,cost);});if(pair_->child()==P::Child::Float)floating_.emplace(pair_->floatInput());return used;}if(scaled_){Q::Credits c{width?bus(a,width):0,10};return scaled_->advanceBefore(cost,c,[&](){return read(a&0xffffff,width,cost);});}if(blend_){B::Credits c{width?bus(a,width):0,10};auto used=blend_->advanceBefore(cost,c,[&](B::Read){return read(a&0xffffff,width,cost);});if(blend_->child()==B::Child::Voice)voice_.emplace();return used;}E::Credits c{width?bus(a,width):0,10};auto used=env_->advanceBefore(cost,c,[&](bool){return read(a&0xffffff,width,cost);});if(env_->child()==E::Child::Float)floating_.emplace(env_->input());return used;}
private:
 void selectNext(){if(blend_&&blend_->complete()){blend_.reset();++stage_;}else if(env_&&env_->complete()){env_.reset();++stage_;}else if(pair_&&pair_->complete()){pair_.reset();++stage_;}else if(scaled_&&scaled_->complete()){scaled_.reset();++stage_;}else return;switch(stage_){case 1:env_.emplace(patch_,0);break;case 2:env_.emplace(patch_,1);break;case 3:blend_.emplace(patch_,1);break;case 4:env_.emplace(patch_,2);break;case 5:env_.emplace(patch_,3);break;case 6:env_.emplace(patch_,4);break;case 7:pair_.emplace(patch_);break;case 8:blend_.emplace(patch_,2);break;case 9:env_.emplace(patch_,5);break;case 10:env_.emplace(patch_,6);break;case 11:env_.emplace(patch_,7);break;case 12:scaled_.emplace(patch_);break;default:break;}}
 static unsigned bus(uint32_t a,unsigned n){int p=-1;unsigned c=0;for(unsigned i=0;i<n;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((p&1)||x!=uint32_t(p|1))c+=x<0x400000?3:1;p=int(x);}else{c+=x>=0xffffa0?1:3;p=-1;}}return c;}void access(uint32_t&a,unsigned&w)const{if(pair_){switch(pair_->stage()){case PS::ReadSquare:a=patch_+0x40;w=1;break;case PS::ReadOffset:a=patch_+0x7d;w=1;break;case PS::ReadPoly:a=patch_+0x81;w=1;break;default:break;}}else if(scaled_){if(scaled_->stage()==QS::Read){a=scaled_->address();w=1;}}else if(blend_){switch(blend_->stage()){case BS::ReadVoice:a=blend_->voice()+6;w=1;break;case BS::ReadDepth:a=blend_->depthAddress();w=1;break;default:break;}}else if(env_){switch(env_->stage()){case ES::ReadValue:a=env_->valueAddress();w=1;break;case ES::ReadOffset:a=env_->offsetAddress();w=2;break;default:break;}}}
 uint32_t patch_;unsigned stage_=0;std::optional<P>pair_{};std::optional<Q>scaled_{};std::optional<B>blend_{};std::optional<E>env_{};std::optional<V>voice_{};std::optional<F>floating_{};
};
}
